import 'package:flutter/widgets.dart';

class AppLocalizations {
  AppLocalizations(this.locale);

  final Locale locale;

  static const supportedLocales = <Locale>[
    Locale('en'),
    Locale('de'),
    Locale('fr'),
    Locale('uk'),
    Locale('it'),
    Locale('pl'),
    Locale('sr'),
    Locale('ru'),
    Locale('pt'),
    Locale('tr'),
    Locale('nl'),
    Locale('sv'),
    Locale('cs'),
    Locale('ro'),
    Locale('hu'),
    Locale('id'),
    Locale('ms'),
    Locale('vi'),
    Locale('zh'),
    Locale('ja'),
    Locale('ko'),
    Locale('hi'),
    Locale('ar'),
    Locale('es'),
  ];

  static const LocalizationsDelegate<AppLocalizations> delegate =
      _AppLocalizationsDelegate();

  static AppLocalizations of(BuildContext context) {
    final value = Localizations.of<AppLocalizations>(context, AppLocalizations);
    assert(value != null, 'AppLocalizations not found in widget tree.');
    return value!;
  }

  String tr(String key, {Map<String, String> params = const {}}) {
    final lang = locale.languageCode.toLowerCase();
    var result = _translations[lang]?[key] ?? _translations['en']?[key] ?? key;
    for (final entry in params.entries) {
      result = result.replaceAll('{${entry.key}}', entry.value);
    }
    return result;
  }

  /// Look up a translation without a [BuildContext].
  ///
  /// Useful for service classes (e.g. notification schedulers) that run
  /// outside the widget tree. Pass the current [languageCode] obtained
  /// from the platform locale; falls back to English, then the raw key.
  static String lookup(
    String key, {
    String languageCode = 'en',
    Map<String, String> params = const {},
  }) {
    final lang = languageCode.toLowerCase();
    var result = _translations[lang]?[key] ?? _translations['en']?[key] ?? key;
    for (final entry in params.entries) {
      result = result.replaceAll('{${entry.key}}', entry.value);
    }
    return result;
  }

